"""Normalise the read-only owner chapter and author complete vector quick checks."""
import argparse,hashlib,json,html
from pathlib import Path
import sympy as s
from fp1_vectors_teaching import lessons
ap=argparse.ArgumentParser();ap.add_argument('--source',required=True);ap.add_argument('--mapping',required=True);ap.add_argument('--assets',required=True);args=ap.parse_args()
source=Path(args.source);owner=json.loads(source.read_text(encoding='utf-8-sig'));audit=json.loads(Path(args.mapping).read_text(encoding='utf8'));media=json.loads(Path(args.assets).read_text(encoding='utf8'))
sha=hashlib.sha256(source.read_bytes()).hexdigest();assert sha==audit['sourceSha256']
M=s.Matrix;tex=s.latex;questions=[];checks=[];images=media['images']
def data(v):return [str(x) for x in v]
def field(key,label,expected,kind='number',**kw):return dict(key=key,label=label,expected=str(expected),type=kind,**kw)
def coords(value,prefix='coord',label='Coordinate'):
    return [field(prefix+str(i+1),label+' '+axis,value[i]) for i,axis in enumerate(['x','y','z'])]
def quick(topic,family,v,title,prompt,fields,solution,ref):
    code={'products':'P','lines':'L','planes':'N','distances':'D','parameters':'T'}[topic];uid=f'M4U-9231-VC-{code}{family}{v}'
    answers=[]
    for f in fields:
        raw=f['expected'];value=html.escape(raw) if f['type'] in ['choice','set'] else r'\('+tex(s.sympify(raw))+r'\)'
        answers.append(html.escape(f['label'])+': '+value)
    questions.append(dict(id=uid,family_uid=f'M4U-9231-VC-{code}{family}',lesson=topic,title=title,collection='short' if v==1 else 'variant',prompt_html=prompt,answer_html='<p>'+'; '.join(answers)+'</p>',solution_html=solution,hint_html='<p>Identify the points and non-zero directions first. Give every requested coordinate or parameter value, and check the original geometric conditions.</p>',marks=len(fields),difficulty=2 if family<3 else 3,fields=fields,parts=[dict(label='',marking_criteria=[dict(code='A1',marks=1,description_html='<p>Give the complete correct '+html.escape(f['label'].lower())+'.</p>') for f in fields])],verification=uid))
    checks.append(dict(uid=uid,answers={f['key']:f['expected'] for f in fields},reference=ref))
def closest(a,u,b,w):
    A,B=s.symbols('A B');q=b+B*w-a-A*u;sol=s.solve([q.dot(u),q.dot(w)],[A,B])
    return a+sol[A]*u,b+sol[B]*w
for v in [1,2]:
    u=M([v+2,1,0]);w=M([1,-v,2]);out=u.cross(w)
    quick('products',1,v,'Give the oriented vector product',rf'<p>Find \(u\times v\), for \(u={tex(u)}\) and \(v={tex(w)}\). Enter all three components in this order.</p>',coords(out,'component','Product component'),rf'\[u\times v={tex(out)}.\]<p>Both dot products vanish; reversing the order would give the negative.</p>',dict(kind='cross',u=data(u),v=data(w)))
    A=M([v,1,0]);B=A+M([3,1,0]);C=A+M([1,-1,2*v]);cross=(B-A).cross(C-A);area=cross.norm()/2;height=cross.norm()/(B-A).norm()
    quick('products',2,v,'Area and the corresponding altitude',rf'<p>For \(A={tex(A)}\), \(B={tex(B)}\), \(C={tex(C)}\), find the area of ABC and the perpendicular distance from C to AB.</p>',[field('area','Triangle area',s.simplify(area)),field('height','Distance from C to AB',s.simplify(height))],rf'<p>The magnitude of \(AB\times AC\) is \({tex(cross.norm())}\). Halve it for area and divide it by \(|AB|={tex((B-A).norm())}\) for height.</p>',dict(kind='triangle',A=data(A),B=data(B),C=data(C)))
    A=M([1,0,0]);B=M([1,2,0]);C=M([1,0,v+1]);volume=s.Rational((v+1)**2,3)
    quick('products',3,v,'Coplanarity before volume',rf'<p>Let \(A={tex(A)}\), \(B={tex(B)}\), \(C={tex(C)}\), \(D=(k,1,1)^T\). Find k for coplanarity. Then find the tetrahedron volume when \(k={v+2}\).</p>',[field('parameter','Coplanar k-value',1),field('volume','Volume when k='+str(v+2),volume)],rf'<p>ABC is the plane x=1, so coplanarity requires k=1. Its triangular area is {v+1}. For the volume part the perpendicular height is {v+1}, giving \({tex(volume)}\).</p>',dict(kind='coplanarity-volume',A=data(A),B=data(B),C=data(C),D=['k','1','1'],volumeK=v+2))
    opts={'A':'v × u has the same direction as u × v.','B':'v × u is the negative of u × v.','C':'Every vector perpendicular to u is equal to u × v.'} if v==1 else {'A':'The three points determine a unique plane.','B':'Any scalar product condition will create a unique plane.','C':'The three points are collinear, so another independent direction is needed.'}
    correct='B' if v==1 else 'C'
    quick('products',4,v,'Check orientation and non-degeneracy','<p>For non-parallel u,v, which statement is correct?</p>' if v==1 else '<p>For three distinct points, AB × AC = 0. Which conclusion is valid?</p>',[field('choice','Correct statement',correct,'choice',options=opts)],'<p>Order fixes the orientation. A zero cross product means dependent directions and cannot define a plane normal.</p>',dict(kind='principle',correct=correct))
    a=M([v,0,1]);u=M([1,v+1,1]);P=a+2*u+M([v+1,-1,0]);H=a+2*u;distance=s.sqrt((v+1)**2+1)
    quick('lines',1,v,'Find the whole perpendicular foot',rf'<p>Find the foot H from \(P={tex(P)}\) to \(r={tex(a)}+t{tex(u)}\), and the exact distance PH.</p>',coords(H,'foot','Foot coordinate')+[field('distance','Perpendicular distance',distance)],rf'<p>The zero scalar-product condition gives t=2. Thus \(H={tex(H)}\), and \(PH={tex(distance)}\).</p>',dict(kind='point-line',a=data(a),u=data(u),P=data(P)))
    a=M([0,0,0]);u=M([1,2,1]);w=M([1,0,-1]);n=u.cross(w);b=3*u-2*w+v*n;distance=s.simplify(abs(b.dot(n))/n.norm())
    quick('lines',2,v,'Calculate the skew separation',rf'<p>Find the exact shortest distance between \(r={tex(a)}+s{tex(u)}\) and \(r={tex(b)}+t{tex(w)}\).</p>',[field('distance','Exact shortest distance',distance)],rf'<p>The directions have product \({tex(n)}\ne0\). The normal projection gives \(d={tex(distance)}\); its non-zero value confirms skewness.</p>',dict(kind='skew-distance',a=data(a),u=data(u),b=data(b),v=data(w)))
    a=M([0,v,0]);u=M([1,1,0]);b=M([1,0,v+2]);w=M([1,-1,0]);P,Q=closest(a,u,b,w)
    quick('lines',3,v,'Give both ends of the shortest segment',rf'<p>For \(r={tex(a)}+s{tex(u)}\) and \(r={tex(b)}+t{tex(w)}\), find both feet P on the first line and Q on the second for their common perpendicular.</p>',coords(P,'first','P coordinate')+coords(Q,'second','Q coordinate'),rf'<p>Solve \((Q-P)\cdot u=(Q-P)\cdot v=0\). This gives \(P={tex(P)}\), \(Q={tex(Q)}\); their connector is normal to both directions.</p>',dict(kind='closest',a=data(a),u=data(u),b=data(b),v=data(w)))
    opts={'A':'They intersect.','B':'They are necessarily distinct and parallel.','C':'They are skew.'} if v==1 else {'A':'Use the point-to-line distance from one anchor to the other line.','B':'Divide the normal separation by |u × v|.','C':'Their shortest distance must be zero.'}
    correct='A'
    quick('lines',4,v,'Classify before choosing a formula',r'<p>Two lines have \(u\times v\ne0\) and \((b-a)\cdot(u\times v)=0\). What follows?</p>' if v==1 else '<p>Two distinct lines have parallel non-zero directions. Which distance method is valid?</p>',[field('choice','Correct conclusion',correct,'choice',options=opts)],'<p>Non-parallel coplanar lines intersect. Parallel directions require a point-to-line formula, because their direction cross product vanishes.</p>',dict(kind='principle',correct=correct))
    A=M([v,1,2]);B=A+M([1,1,0]);C=A+M([0,1,v+1]);n=(B-A).cross(C-A);n=n/n[0];d=n.dot(A)
    quick('planes',1,v,'Give every normalised plane coefficient',rf'<p>Find the plane through \(A={tex(A)}\), \(B={tex(B)}\), \(C={tex(C)}\). Write it as \(x+By+Cz=D\), so the coefficient of x is fixed as 1. Give B,C,D exactly.</p>',[field('coef_b','Coefficient B',n[1]),field('coef_c','Coefficient C',n[2]),field('constant','Constant D',s.simplify(d))],rf'<p>Use the vector product of AB and AC, then divide the whole normal by its x-component. The coefficients are \(({tex(n[1])},{tex(n[2])},{tex(d)})\).</p>',dict(kind='plane',A=data(A),B=data(B),C=data(C)))
    a=M([v,0,1]);u=M([1,1,1]);n=M([1,-1,v+1]);d=3*v+2;X=a+u
    quick('planes',2,v,'Find the complete crossing point',rf'<p>Find X where \(r={tex(a)}+t{tex(u)}\) meets \(x-y+{v+1}z={d}\).</p>',coords(X,'point','X coordinate'),rf'<p>Substitution gives t=1, and \(X={tex(X)}\). The coefficient of t is {v+1}, so there is exactly one crossing.</p>',dict(kind='line-plane',a=data(a),u=data(u),n=data(n),d=str(d)))
    a=M([v+2,1,0]);u=M([-1,0,1])
    quick('planes',3,v,'Give a complete intersection line',rf'<p>Find the line of intersection of \(x+y+z={v+3}\) and \(x-y+z={v+1}\). Give an anchor with z=0 and a direction whose z-component is 1.</p>',coords(a,'anchor','Anchor coordinate')+coords(u,'direction','Direction component'),rf'<p>Subtracting gives y=1, then x+z={v+2}. The requested normalisation gives anchor \({tex(a)}\) and direction \({tex(u)}\).</p>',dict(kind='planes-line',n1=['1','1','1'],d1=str(v+3),n2=['1','-1','1'],d2=str(v+1)))
    opts={'A':'The line has exactly one crossing.','B':'The line is parallel and disjoint.','C':'The whole line lies in the plane.'} if v==1 else {'A':'A unique plane is determined.','B':'The parametrisation describes at most a line.','C':'The parametrisation describes all of space.'}
    correct='C' if v==1 else 'B'
    quick('planes',4,v,'Check the exceptional plane condition',r'<p>For \(r=a+tu\) and \(n\cdot r=d\), both \(n\cdot u=0\) and \(n\cdot a=d\). What is the configuration?</p>' if v==1 else '<p>A two-parameter description uses parallel non-zero direction vectors. What can it describe?</p>',[field('choice','Correct conclusion',correct,'choice',options=opts)],'<p>Containment requires both the anchor and direction conditions. A plane needs two independent directions.</p>',dict(kind='principle',correct=correct))
    n=M([1,2,2]);d=3*v;H=M([v,0,v]);P=H+(v+1)*n
    quick('distances',1,v,'Foot and distance from a plane',rf'<p>For \(P={tex(P)}\) and \(x+2y+2z={d}\), give the perpendicular foot H and distance PH.</p>',coords(H,'foot','Foot coordinate')+[field('distance','Perpendicular distance',3*(v+1))],rf'<p>The normal has magnitude 3. Removing its signed component gives \(H={tex(H)}\) and distance {3*(v+1)}.</p>',dict(kind='point-plane',n=data(n),d=str(d),P=data(P)))
    n=M([1,-1,2]);u=M([v+1,1,1]);m=M([1,v,0]);sine=s.simplify(abs(u.dot(n))/(u.norm()*n.norm()));cosine=s.simplify(abs(n.dot(m))/(n.norm()*m.norm()))
    quick('distances',2,v,'Give the two correct trigonometric ratios',rf'<p>A line has direction \({tex(u)}\). Plane \(\Pi\) has normal \({tex(n)}\), and plane \(\Sigma\) has normal \({tex(m)}\). Let \(\alpha\) be the smaller line–\(\Pi\) angle and \(\beta\) the smaller \(\Pi\)–\(\Sigma\) angle, allowing right angles. Give \(\sin\alpha\) and \(\cos\beta\) exactly.</p>',[field('sine','sin alpha',sine),field('cosine','cos beta',cosine)],rf'<p>Use the absolute scalar products, and sine for the line–plane angle. The ratios are \({tex(sine)}\) and \({tex(cosine)}\).</p>',dict(kind='angles',u=data(u),n=data(n),m=data(m)))
    n=M([1,2,2]);d=3*v;H=M([v,0,v]);P=H+(v+1)*n;R=2*H-P;u=M([2,-1,v]);projected=u-u.dot(n)/n.dot(n)*n
    quick('distances',3,v,'Reflect the point and project the direction',rf'<p>For plane \(x+2y+2z={d}\), reflect \(P={tex(P)}\) to R. Also find the orthogonal projection of the vector \(u={tex(u)}\) onto a direction parallel to the plane. Give the actual projected vector, without rescaling.</p>',coords(R,'reflection','R coordinate')+coords(projected,'projected','Projected component'),rf'<p>The perpendicular foot is \({tex(H)}\), so \(R=2H-P={tex(R)}\). For the vector, remove \((u\cdot n)n/(n\cdot n)\), giving \({tex(projected)}\).</p>',dict(kind='reflection-projection',n=data(n),d=str(d),P=data(P),u=data(u)))
    opts={'A':'The normal direction is unchanged by reflection.','B':'The reflected point is twice as far from the plane.','C':'The foot is the midpoint of a point and its reflection.'} if v==1 else {'A':'A single point.','B':'A line with zero direction.','C':'An entire plane.'}
    correct='C' if v==1 else 'A'
    quick('distances',4,v,'Interpret the geometric map','<p>Which reflection statement is correct?</p>' if v==1 else '<p>A line is perpendicular to a plane. What is its orthogonal projection onto that plane?</p>',[field('choice','Correct statement',correct,'choice',options=opts)],'<p>Reflection fixes the foot and reverses the normal displacement. Orthogonal projection removes that component, so a normal line collapses to its foot.</p>',dict(kind='principle',correct=correct))
    k=s.Symbol('k',real=True);a=M([k-v,0,0]);u=M([(k-v)*(k-v-2),1,0])
    quick('parameters',1,v,'Separate containment from disjoint parallelism',rf'<p>Classify \(r={tex(a)}+t{tex(u)}\) relative to \(x=0\). Give the complete sets of k-values for containment and for parallel disjointness. For every other k there is one crossing.</p>',[field('contained','All contained k-values','{'+str(v)+'}','set'),field('parallel','All parallel disjoint k-values','{'+str(v+2)+'}','set')],rf'<p>The intersection equation factors as \((k-{v})[1+t(k-{v+2})]=0\). Containment occurs at {v}; at {v+2} a non-zero constant remains.</p>',dict(kind='line-plane-family',a=data(a),u=data(u),n=['1','0','0'],d='0',variable='k'))
    n=M([1,2,-2]);P=M([k,v,1]);target=v+1;roots=[2-2*v-3*target,2-2*v+3*target]
    quick('parameters',2,v,'Keep both signed distance cases',rf'<p>For \(P=(k,{v},1)\) and plane \(x+2y-2z=0\), find all real k for which the distance is {target}.</p>',[field('values','All real k-values','{'+','.join(str(t) for t in roots)+'}','set')],rf'<p>The equation is \(|k+{2*v}-2|=3({target})\). Both signs are allowed, giving \({roots[0]}\) and \({roots[1]}\).</p>',dict(kind='distance-roots',n=data(n),d='0',P=data(P),target=str(target),variable='k'))
    a=M([0,0,0]);u=M([1,0,0]);b=M([0,v+1,v]);w=M([1,k-v,0])
    quick('parameters',3,v,'Recompute the parallel exception',rf'<p>For \(r=s{tex(u)}\) and \(r={tex(b)}+t{tex(w)}\), find the parallel k-value, the distance at that value, and the distance for every other real k.</p>',[field('parallel','Parallel k-value',v),field('at_parallel','Distance at the parallel value',s.sqrt(v*v+(v+1)**2)),field('otherwise','Distance at every other k',v)],rf'<p>The directions become parallel at k={v}. Their distance then is \({tex(s.sqrt(v*v+(v+1)**2))}\). Otherwise the common normal is vertical, giving distance {v}.</p>',dict(kind='parallel-exception',a=data(a),u=data(u),b=data(b),v=data(w),variable='k',parallel=v))
    opts={'A':'A line is still defined, with arbitrary direction.','B':'The formula no longer defines a line.','C':'The line becomes a plane.'} if v==1 else {'A':'Cancel first and ignore the exceptional value.','B':'Only the limit at the cancelled value matters.','C':'Check the exceptional value in the original equations.'}
    correct='B' if v==1 else 'C'
    quick('parameters',4,v,'Preserve the exceptional case','<p>A parameter makes every component of a line direction zero. What follows?</p>' if v==1 else '<p>An intersection calculation contains a factor k−2. What must be done before dividing by it?</p>',[field('choice','Correct conclusion',correct,'choice',options=opts)],'<p>Non-zero directions and normals define the geometric objects. A cancelled value must be classified from the original conditions.</p>',dict(kind='principle',correct=correct))

topic_map={'Vector products and geometric applications':'products','Skew lines and common perpendiculars':'lines','Angles and intersections of planes':'planes','Planes and perpendicular projections':'planes','Distances and perpendicular projections':'distances','Intersections and relative positions':'distances','Geometric applications and reflections':'distances','Parameter problems and exceptional cases':'parameters'}
mapping={r['id']:r for r in audit['rows']};rows=[];fixtures=[]
def digest(q):return hashlib.sha256('\0'.join([q['title'],q['prompt_html'],q['answer_html'],q['solution_html'],q['hint_html'],str(q['marks'])]).encode()).hexdigest()
for q in [q for l in owner['lessons'] for q in l['questions']]:
    row=mapping[str(q['id'])];key=topic_map[q['topic']];refs={a['source_name']:'/api/files/'+a['file_id'] for a in images if a['question_uid']==q['content_uid']}
    def normalise(value):
        for old,new in refs.items():value=value.replace(old,new)
        return value
    assert sum(p['marks'] for p in q['parts'])==q['marks']==q['mark_scheme']['total_marks']
    parts=[]
    for index,p in enumerate(q['parts']):
        criteria=[dict(code=c['code'],marks=c['marks'],description_html=normalise(c['criterion_html'])) for c in p['criteria']]
        assert sum(c['marks'] for c in criteria)==p['marks']
        parts.append(dict(label=chr(97+index),marking_criteria=criteria))
    item=dict(id=q['content_uid'],family_uid=q['content_uid'],lesson=key,title=q['title'],collection='exam',prompt_html=normalise(q['question_html']),answer_html=normalise(q['answer_html']),solution_html=normalise(q['solution_html']),hint_html=normalise(q['hint_html']),marks=q['marks'],difficulty=q['difficulty'],fields=[],parts=parts,provenance=dict(original_id=q['provenance']['original_id'],original_uid=q['provenance']['original_uid'],archiveTaskId=row['archiveTaskId'],sourceSha256=sha,ownerProvenance=q['provenance']),verification='OWNER-'+str(q['id']))
    questions.append(item);rows.append({**row,'lesson':key,'marks':q['marks'],'contentSha256':digest(item)})
    fixtures.append(dict(id=str(q['id']),uid=q['content_uid'],bank_number=q['bank_number'],stem_html=q['stem_html'],parts=q['parts'],contentSha256=digest(item)))
for row in checks:row['contentSha256']=digest(next(q for q in questions if q['id']==row['uid']))
assets=[{k:v for k,v in a.items() if k not in ['source_name','source_sha256']} for a in images]
package=dict(schema_version=1,key='9231-fp1-vectors',version='1.0.0',course=dict(slug='maths4u-9231-fp1',title='Further Pure Mathematics 1 (9231)',code='9231',direction='further'),chapter=dict(id='fp1_vectors',slug='vectors',title='Vectors',position=5),source=dict(sha256=sha,supplied=84,held=[]),lessons=lessons,questions=questions,marking_status='DRAFT',assets=assets)
