out=Path('content/original/9231-fp1');write(out/'vectors-v1.json',package);write(out/'vectors-quick-verification-v1.json',checks);write(out/'vectors-owner-verification-v1.json',fixtures)
write(Path('docs/ARENA-C2-VECTORS-SOURCE-AUDIT-20261106.json'),dict(sourceSha256=sha,rows=rows,editorialRepairs=[],images=images,mediaSource=media['mediaSource'],book=dict(path='D:/new_books/furhter_cambridge.pdf',pdfPages=[131,149],printedPages=[119,137],structure=[dict(section='6.1',lessons=['products']),dict(section='6.2',lessons=['lines']),dict(section='6.3',lessons=['planes','distances']),dict(section='Mixed extension of 6.1–6.3',lessons=['parameters'])],use='Mathematical order only; independently authored teaching, no book exercises or illustrations.'),teachingDigests={l['id']:hashlib.sha256(json.dumps(l,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest() for l in lessons}))
